package com.alg.greedy;

import java.util.Arrays;
import java.util.Collection;
import java.util.Comparator;

/**
 * Created by HAU on 11/21/2017.
 */
/*Given a collection of intervals, find the minimum number of intervals you need to remove to make the rest of the intervals non-overlapping.

Note:
You may assume the interval's end point is always bigger than its start point.
Intervals like [1,2] and [2,3] have borders "touching" but they don't overlap each other.
Example 1:
Input: [ [1,2], [2,3], [3,4], [1,3] ]

Output: 1

Explanation: [1,3] can be removed and the rest of intervals are non-overlapping.*/
public class Sol435_NonoverlappingIntervals {
    public static class Interval {
        int start;
        int end;
        Interval() { start = 0; end = 0; }
        Interval(int s, int e) { start = s; end = e; }
    }
    public static int eraseOverlapIntervals(Interval[] intervals) {
        if (intervals.length == 0) return 0;
        Arrays.sort(intervals, new myComparator());
        int end = intervals[0].end;
        int count = 1;
        for (int i = 1; i < intervals.length; i++){
            if(intervals[i].start >= end){
                count++;
                end = intervals[i].end;
            }
        }
        return intervals.length - count;
        /*

    Time complexity : O(nlog(n)). Sorting takes  time.

    Space complexity : O(1) No extra space is used.
*/
    }

    public static class myComparator implements Comparator<Interval>{
        public int compare(Interval a, Interval b){
            return a.end - b.end;
        }
    }

    public static void main(String[] args) {
        Interval a1 = new Interval(1,3);
        Interval a2 = new Interval(3,5);
        Interval a3 = new Interval(6,13);
        Interval a4 = new Interval(3,8);
        Interval[] ia = {a1,a2,a3,a4};
        System.out.println(eraseOverlapIntervals(ia));
        System.out.println(eraseOverlap(ia));

        int[][] intervals = { {1,100}, {11,22}, {1,11}, {2,12}};
        Sol435_NonoverlappingIntervals ss = new Sol435_NonoverlappingIntervals();
        System.out.println(ss.eraseOverlapIntervals3(intervals));

    }
    // method 2, sort by start
    public static int eraseOverlap(Interval[] intervals){
        if (intervals.length == 0) return 0;
        //Arrays.sort(intervals, new startComparator());
        Arrays.sort(intervals, new Comparator<Interval>() {
            @Override
            public int compare(Interval o1, Interval o2) {
                return o1.start - o2.start;
            }
        });
        int prev = 0, count = 0;
        for ( int i = 1; i < intervals.length; i++){
            if (intervals[prev].end > intervals[i].start){
                count++;
                if (intervals[prev].end > intervals[i].end) prev = i;
            }else{
                prev = i;
            }
        }
        return count;

    }

    private static class startComparator implements Comparator<Interval>{
        public int compare(Interval a, Interval b){
            return a.start - b.start;
        }
    }

    public int eraseOverlapIntervals(int[][] intervals) {
        // Arrays.sort(intervals, (i1, i2) -> i1[1] - i2[1]); // sort by right end; works as well, preserve order for equal case
        Arrays.sort(intervals, (i1, i2) ->
                i1[1] == i2[1] ?  i1[0] - i2[0] : i1[1] - i2[1]); // sort by right end, if equal, sort by left end; does not change the result
        int nonOver = 1;  // initiate as 1
        int currentEnd = intervals[0][1];
        for (int i = 1; i < intervals.length; i++) {
            if (intervals[i][0] >= currentEnd) {
                nonOver++;
                currentEnd = intervals[i][1];
            }
        }
        return intervals.length - nonOver;

    }
    // https://github.com/youngyangyang04/leetcode-master/blob/master/problems/0435.%E6%97%A0%E9%87%8D%E5%8F%A0%E5%8C%BA%E9%97%B4.md
    //按左边排序，不管右边顺序。相交的时候取最小的右边。
    public int eraseOverlapIntervals3(int[][] intervals) {
        if (intervals == null || intervals.length == 0) {
            return 0;
        }
        int n = intervals.length;
//        Arrays.sort(intervals, Comparator.comparingInt(i -> i[0]));
        Arrays.sort(intervals, ((o1, o2) -> {
            if (o1[0] == o2[0]) {
                return o1[1] - o2[1];
            }
            return o1[0] - o2[0];
        }));
        int remove = 0;
        int end = intervals[0][1];
        for (int i = 1; i < n; i++) {
            if (intervals[i][0] < end) {
                remove++;
                end = Math.min(end, intervals[i][1]);
            } else {
                end = intervals[i][1];
            }
        }
        return remove;
    }

    public int eraseOverlapIntervals2(int[][] intervals) {
        Arrays.sort(intervals, (i1,i2) -> Integer.compare(i1[0], i2[0]));
        // sort by start
        if (intervals.length == 0) return 0;
        int n = intervals.length;
        int toRemove = 0;
        int end = intervals[0][1];
        for (int i = 1; i < n; i++) {
            int[] cur = intervals[i];
            if (cur[0] < end) {
                toRemove++;
                end = Math.min(cur[1], end);
            } else {
                end = cur[1];
            }
        }
        return toRemove;

    }
}

package Arrays;

import java.util.Stack;
//                      Given a balanced parentheses string S, compute the score of the string based on the following rule:
//
//                              () has score 1
//                              AB has score A + B, where A and B are balanced parentheses strings.
//                              (A) has score 2 * A, where A is a balanced parentheses string.
//
//
//
//                              Example 1:
//
//                              Input: "()"
//                              Output: 1
//
//                              Example 2:
//
//                              Input: "(())"
//                              Output: 2
//
//                              Example 3:
//
//                              Input: "()()"
//                              Output: 2
//
//                              Example 4:
//
//                              Input: "(()(()))"
//                              Output: 6

public class ScoreOfParenthesis {
    public static void main(String[] args) {

    }

//    Call a balanced string primitive if it cannot be partitioned into two non-empty balanced strings.
//
//    By keeping track of balance (the number of ( parentheses minus the number of ) parentheses), we
//    can partition S into primitive substrings S = P_1 + P_2 + ... + P_n. Then, score(S) = score(P_1)
//    + score(P_2) + ... + score(P_n), by definition.
//
//    For each primitive substring (S[i], S[i+1], ..., S[k]), if the string is length 2, then the
//    score of this string is 1. Otherwise, it's twice the score of the substring (S[i+1], S[i+2], ..., S[k-1]).
    private static int scoreOfParenthesis(String s) {
        return findScore(s, 0, s.length());
    }

    private static int findScore(String s, int i, int length) {
        // Score of balanced string s[i:j]
        int ans = 0, bal = 0;

        // Split string into primitives
        for (int k = i; k < length; k++) {
            bal += s.charAt(k) == '(' ? 1 : -1;
            if (bal == 0) {
                if (k - i == 1) ans++;
                else ans += 2 * findScore(s, i + 1, k);
                i = k + 1;
            }
        }
        return ans;
    }


//    Every position in the string has a depth - some number of matching parentheses surrounding it.
    //    For example, the dot in (()(.())) has depth 2, because of these parentheses: (__(.__))
//
//    Our goal is to maintain the score at the current depth we are on. When we see an opening bracket,
    //    we increase our depth, and our score at the new depth is 0. When we see a closing bracket,
    //    we add twice the score of the previous deeper part - except when counting (), which has a score of 1.
//
//    For example, when counting (()(())), our stack will look like this:
//
//            [0, 0] after parsing (
//    [0, 0, 0] after (
//            [0, 1] after )
//            [0, 1, 0] after (
//    [0, 1, 0, 0] after (
//            [0, 1, 1] after )
//    [0, 3] after )
//            [6] after )

    private static int scoreOfParenthesisStack(String s) {
        Stack<Integer> stack = new Stack<>();
        stack.push(0); // the score of current frame

        for (char c : s.toCharArray()) {
            if (c == '(')
                stack.push(0);
            else {
                int v = stack.pop();
                int w = stack.pop();
                stack.push(w + Math.max(2 * v, 1));
            }
        }
    return stack.pop();
    }

//    Intuition
//
//    The final sum will be a sum of powers of 2, as every core (a substring (), with score 1)
    //    will have it's score multiplied by 2 for each exterior set of parentheses that contains that core.
//
//    Algorithm
//
//    Keep track of the balance of the string, as defined in Approach #1. For every ) that immediately
    //    follows a (, the answer is 1 << balance, as balance is the number of exterior set of parentheses that contains this core.

    private static int scoreOfParenthesis2(String s) {
        int ans = 0, bal = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '(') {
                bal ++;
            } else {
                bal --;
                if (s.charAt(i-1) == '(')
                    ans += 1 << bal;
            }
        }

        return ans;
    }
}

